+async function withIsolatedServer(run){
+  const isolatedDir=fs.mkdtempSync(path.join(os.tmpdir(),'library-regression-'));
+  const isolatedFile=path.join(isolatedDir,'library.json');
+  const isolatedChild=spawn(process.execPath,['server.js'],{env:{...process.env,PORT:'0',DATA_FILE:isolatedFile},stdio:['ignore','pipe','inherit']});
+  let isolatedBase;
+  try {
+    let output='';
+    await new Promise((resolve,reject)=>{
+      isolatedChild.stdout.on('data',chunk=>{output+=chunk;const m=output.match(/LISTENING_ON_PORT=(\d+)/);if(m){isolatedBase='http://127.0.0.1:'+m[1];resolve();}});
+      isolatedChild.once('error',reject);
+      setTimeout(()=>reject(new Error('isolated server timeout')),5000);
+    });
+    const isolatedRequest=async(method,pathName,body,headers={})=>{
+      const r=await fetch(isolatedBase+pathName,{method,headers:{'content-type':'application/json','X-Today':'2026-01-01',...headers},body:body===undefined?undefined:JSON.stringify(body)});
+      return {status:r.status,json:await r.json()};
+    };
+    await run(isolatedRequest);
+  } finally {
+    isolatedChild.kill('SIGTERM');
+    fs.rmSync(isolatedDir,{recursive:true,force:true});
+  }
+}
