+test('isolated premium lending boundary derives IDs and preserves five active loans',async()=>{
+  await withIsolatedServer(async request=>{
+    let r=await request('GET','/api/members');assert.equal(r.status,200);
+    const premium=r.json.find(member=>member.type==='premium');assert.ok(premium?.id);
+    r=await request('GET','/api/books');assert.equal(r.status,200);
+    const availableBooks=r.json.filter(book=>book.availableCopies>0);assert.ok(availableBooks.length>=6);
+    const loanBooks=availableBooks.slice(1,6).map(book=>book.id);
+    assert.equal(loanBooks.length,5);
+    for(const bookId of loanBooks){
+      r=await request('POST','/api/loans',{bookId,memberId:premium.id});
+      assert.equal(r.status,201);assert.ok(r.json.id);assert.equal(r.json.bookId,bookId);assert.equal(r.json.memberId,premium.id);
+    }
+    r=await request('GET','/api/members/'+premium.id);assert.equal(r.status,200);
+    assert.equal(r.json.activeLoans.length,5);assert.equal(r.json.finesOwedCents,0);
+    r=await request('GET','/api/books');assert.equal(r.status,200);
+    const sixthBook=r.json.find(book=>book.id===availableBooks[0].id);assert.ok(sixthBook);assert.ok(sixthBook.availableCopies>0);
+    r=await request('POST','/api/loans',{bookId:sixthBook.id,memberId:premium.id});
+    assert.equal(r.status,409);assert.equal(r.json.error,'loan limit reached');
+    r=await request('GET','/api/members/'+premium.id);assert.equal(r.status,200);assert.equal(r.json.activeLoans.length,5);
+  });
+});
