+test('isolated fine boundaries use observed balances and counts',async()=>{
+  for(const [paymentAmount,expectedBalance,shouldLend] of [[5.01,499,true],[5,500,true],[4.99,501,false]]){
+    await withIsolatedServer(async request=>{
+      let r=await request('GET','/api/members');assert.equal(r.status,200);
+      const member=r.json.find(candidate=>candidate.type==='premium');assert.ok(member?.id);
+      r=await request('GET','/api/books');assert.equal(r.status,200);
+      const book=r.json.find(candidate=>candidate.availableCopies>0);assert.ok(book?.id);
+      r=await request('POST','/api/loans',{bookId:book.id,memberId:member.id});
+      assert.equal(r.status,201);assert.ok(r.json.id);
+      const loanId=r.json.id;
+      r=await request('POST','/api/loans/'+loanId+'/return',undefined,{'X-Today':'2026-02-25'});
+      assert.equal(r.status,200);assert.equal(r.json.id,loanId);assert.equal(r.json.fineCents,1000);
+      r=await request('POST','/api/members/'+member.id+'/payments',{amount:paymentAmount});
+      assert.equal(r.status,201);assert.ok(r.json.id);assert.equal(r.json.amountCents,Math.round(paymentAmount*100));
+      r=await request('GET','/api/members/'+member.id);assert.equal(r.status,200);
+      assert.equal(r.json.finesOwedCents,expectedBalance);assert.equal(r.json.activeLoans.length,0);
+      r=await request('GET','/api/books');assert.equal(r.status,200);
+      const lendable=r.json.find(candidate=>candidate.id===book.id);assert.ok(lendable);assert.ok(lendable.availableCopies>0);
+      r=await request('POST','/api/loans',{bookId:book.id,memberId:member.id});
+      if(shouldLend){assert.equal(r.status,201);assert.ok(r.json.id);}
+      else {assert.equal(r.status,409);assert.equal(r.json.error,'fine threshold exceeded');}
+      r=await request('GET','/api/members/'+member.id);assert.equal(r.status,200);
+      assert.equal(r.json.activeLoans.length,shouldLend?1:0);
+    });
+  }
+});
